    .select({ value: count() })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(and(...filters))
    .get();

  const rows = db
    .select({ member: members, user: users })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(members.createdAt), desc(members.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => ({ ...toMember(row.member), user: toUser(row.user) }),
    (row) => ({ id: row.member.id, sortValue: row.member.createdAt }),
  );
}

/** The seat count every plan check compares against. */
export async function countActiveMembers(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertMember(
  orgId: OrgId,
  userId: UserId,
  role: Role,
  invitedBy: UserId | null,
): Promise<Member> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(members)
    .values({
      id: newId(),
      orgId,
      userId,
      role,
      status: "active",
      invitedBy,
      joinedAt: stamp,
      lastSeenAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMember(row);
}

export async function updateMemberRole(
  orgId: OrgId,
  memberId: MemberId,
  role: Role,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({ role, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

/** Removal is a soft delete so the audit log keeps pointing at a real row. */
export async function archiveMember(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({ ...archivePatch(), status: "suspended" })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

export async function touchLastSeen(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(members)
    .set({ lastSeenAt: at })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.userId, userId)))
    .run();
}
/**
 * Private row → domain mappers for the repository layer.
 *
 * SQLite stores branded ids as plain text and collections as JSON strings, so
 * exactly one place is allowed to re-apply the brands and parse the JSON: here.
 * Services never see a `*Row` type.
 */
import type {
  ActivityEventRow,
  AttachmentRow,
  CommentRow,
  InvitationRow,
  InvoiceRow,
  IssueRow,
  LabelRow,
  MemberRow,
  NotificationPreferenceRow,
  NotificationRow,
  OrganizationRow,
  OrganizationUsageRow,
  ProjectRow,
  SubscriptionRow,
  UserRow,
} from "@/server/db";
import type {
  ActivityAction,
  ActivityEvent,
} from "@/types/activity";
import type { Invoice, Subscription } from "@/types/billing";
import type { Comment } from "@/types/comment";
import type {
  ActivityId,
  AttachmentId,
  CommentId,
  InvitationId,
  IsoTimestamp,
  IssueId,
  LabelId,
  MemberId,
  NotificationId,
  OrgId,
  ProjectId,
  SubscriptionId,
  UserId,
} from "@/types/common";
import type { Issue, IssueAttachment, IssueLabel } from "@/types/issue";
import type { Invitation, Member, User } from "@/types/member";
import type {
  Notification,
  NotificationChannel,
  NotificationPreference,
} from "@/types/notification";
import type {
  Organization,
  OrganizationUsage,
} from "@/types/organization";
import type { Project } from "@/types/project";

/** Every id column is text in SQLite; the brand is re-applied on the way out. */
export function brandId<T extends string>(value: string): T {
  return value as T;
}

export function brandStamp(value: string): IsoTimestamp {
  return value as IsoTimestamp;
}

export function brandStampOrNull(value: string | null): IsoTimestamp | null {
  return value === null ? null : brandStamp(value);
}

/** Tolerant JSON array read: a corrupt column degrades to an empty list. */
import { index, integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import {
  idColumn,
  softDeleteColumns,
  tenantColumns,
  timestampColumns,
} from "./_shared";

export const issues = sqliteTable(
  "issues",
  {
    id: idColumn(),
    ...tenantColumns,
    projectId: text("project_id").notNull(),
    number: integer("number").notNull(),
    title: text("title").notNull(),
    description: text("description"),
    status: text("status", {
      enum: ["backlog", "todo", "in_progress", "in_review", "done", "canceled"],
    })
      .notNull()
      .default("backlog"),
    priority: text("priority", {
      enum: ["none", "low", "medium", "high", "urgent"],
    })
      .notNull()
      .default("none"),
    authorId: text("author_id").notNull(),
    assigneeId: text("assignee_id"),
    parentId: text("parent_id"),
    estimate: integer("estimate"),
    dueAt: text("due_at"),
    startedAt: text("started_at"),
    completedAt: text("completed_at"),
    ...timestampColumns,
    ...softDeleteColumns,
  },
  (table) => [
    uniqueIndex("issues_project_number_idx").on(table.projectId, table.number),
    index("issues_org_status_idx").on(table.orgId, table.status),
    index("issues_org_assignee_idx").on(table.orgId, table.assigneeId),
    index("issues_org_archived_idx").on(table.orgId, table.archivedAt),
    index("issues_org_due_idx").on(table.orgId, table.dueAt),
  ],
);

export const labels = sqliteTable(
  "labels",
  {
    id: idColumn(),
    ...tenantColumns,
    name: text("name").notNull(),
    color: text("color").notNull().default("#94a3b8"),
    description: text("description"),
    ...timestampColumns,
  },
  (table) => [uniqueIndex("labels_org_name_idx").on(table.orgId, table.name)],
);

export const issueLabels = sqliteTable(
  "issue_labels",
  {
    ...tenantColumns,
    issueId: text("issue_id").notNull(),
    labelId: text("label_id").notNull(),
  },
  (table) => [
    uniqueIndex("issue_labels_pk").on(table.issueId, table.labelId),
    index("issue_labels_org_idx").on(table.orgId),
  ],
);

export const attachments = sqliteTable(
  "attachments",
  {
    id: idColumn(),
    ...tenantColumns,
    issueId: text("issue_id").notNull(),
    filename: text("filename").notNull(),
    contentType: text("content_type").notNull(),
    sizeBytes: integer("size_bytes").notNull(),
    uploadedBy: text("uploaded_by").notNull(),
    ...timestampColumns,
  },
  (table) => [index("attachments_org_issue_idx").on(table.orgId, table.issueId)],
);

export type IssueRow = typeof issues.$inferSelect;
export type NewIssueRow = typeof issues.$inferInsert;
export type LabelRow = typeof labels.$inferSelect;
export type AttachmentRow = typeof attachments.$inferSelect;

