/**
 * Validation of the things a write points at: labels, parent issues, parent
 * comments and people. Everything referenced must be usable from the org the
 * change is made in. A reference owned by another org is refused as a tenant
 * scope violation; one that is missing, archived or otherwise out of reach is
 * refused as not found. These run before any write so a refusal changes
 * nothing.
 */
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError } from "./_support";
import type { Comment } from "@/types/comment";
import type {
  CommentId,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";

/** True when `userId` is a live, active member of `orgId`. */
export async function isCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<boolean> {
  const member = await memberRepo.findMember(orgId, userId);
  return member !== null && member.status === "active";
}

/** Assignees and project leads must be current members of the org. */
export async function assertCurrentMember(
  orgId: OrgId,
  userId: UserId,
  entity = "Member",
): Promise<void> {
  if (!(await isCurrentMember(orgId, userId))) {
    throw new NotFoundError(entity, userId);
  }
}

/** Every label id must name one of the org's own labels. */
export async function assertOwnLabels(
  actor: Actor,
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<void> {
  if (labelIds.length === 0) return;
  const found = await labelRepo.findLabelsByIdsAnyOrg(labelIds);
  const byId = new Map(found.map((label) => [label.id as string, label]));

  for (const labelId of labelIds) {
    const label = byId.get(labelId);
    if (label && label.orgId !== orgId) assertOrgScope(actor, label.orgId);
  }
  for (const labelId of labelIds) {
    if (!byId.has(labelId)) throw new NotFoundError("Label", labelId);
  }
}

/** A parent issue must be a live issue of the same project. */
export async function assertValidParentIssue(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = await issueRepo.findIssueByIdAnyOrg(parentId);
  if (parent && parent.orgId !== orgId) assertOrgScope(actor, parent.orgId);
  if (
    !parent ||
    parent.orgId !== orgId ||
    isArchived(parent) ||
    parent.projectId !== projectId
  ) {
    throw new NotFoundError("Issue", parentId);
  }
  return parent;
}

/** A reply must be to a live, top-level comment on the same issue. */
export async function assertValidParentComment(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
  parentId: CommentId,
): Promise<Comment> {
  const parent = await commentRepo.findCommentByIdAnyOrg(parentId);
  if (parent && parent.orgId !== orgId) assertOrgScope(actor, parent.orgId);
  if (
    !parent ||
    parent.orgId !== orgId ||
    isArchived(parent) ||
    parent.issueId !== issueId ||
    parent.parentId !== null
  ) {
    throw new NotFoundError("Comment", parentId);
  }
  return parent;
}

